PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_offer_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),plan_id TEXT NOT NULL REFERENCES training_plans(id),slot_id TEXT NOT NULL REFERENCES schedule_slots(id),serial INTEGER NOT NULL CHECK(serial>0),offer_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES family_offer_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,offer_number),FOREIGN KEY(first_version_id,id) REFERENCES family_offer_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_offer_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_offer_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES family_offer_events(id) DEFERRABLE INITIALLY DEFERRED,schedule_prefix INTEGER NOT NULL CHECK(schedule_prefix>0),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),public_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES family_offer_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE family_offer_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_offer_roots(id),version_id TEXT NOT NULL REFERENCES family_offer_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('publish','withdraw')),status TEXT NOT NULL CHECK(status IN('published','withdrawn')),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE TABLE family_offer_selections(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),offer_id TEXT NOT NULL REFERENCES family_offer_roots(id),version_id TEXT NOT NULL REFERENCES family_offer_versions(id),request_id TEXT NOT NULL UNIQUE REFERENCES family_request_roots(id),request_prefix INTEGER NOT NULL CHECK(request_prefix>0),offer_prefix INTEGER NOT NULL CHECK(offer_prefix>0),source_json TEXT NOT NULL CHECK(json_valid(source_json)),schedule_prefix INTEGER NOT NULL CHECK(schedule_prefix>0),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE family_offer_admissions(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),selection_id TEXT NOT NULL UNIQUE REFERENCES family_offer_selections(id),booking_id TEXT NOT NULL UNIQUE REFERENCES schedule_bookings(id),booking_event_id TEXT NOT NULL UNIQUE REFERENCES schedule_booking_events(id),offer_prefix INTEGER NOT NULL CHECK(offer_prefix>0),request_revision INTEGER NOT NULL CHECK(request_revision>0),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
CREATE VIEW family_offer_current AS SELECT e.* FROM family_offer_events e WHERE e.revision=(SELECT max(revision) FROM family_offer_events WHERE root_id=e.root_id);
CREATE VIEW family_offer_sources AS SELECT p.id plan_id,p.plan_number,p.customer_id,p.store_id,p.cycle_id,p.cycle_version,e.plan_version,e.revision plan_revision,e.id plan_event_id,e.status plan_status,s.id slot_id,s.slot_number,t.revision slot_revision,t.id slot_event_id,t.kind slot_kind,t.capacity,t.starts_at,t.ends_at,t.resources_json FROM training_plans p JOIN training_plan_events e ON e.plan_id=p.id JOIN schedule_slots s ON s.store_id=p.store_id JOIN schedule_slot_events t ON t.slot_id=s.id WHERE e.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=p.id) AND t.revision=(SELECT max(revision) FROM schedule_slot_events WHERE slot_id=s.id) AND t.status='active' AND t.kind<>'maintenance';
CREATE TRIGGER family_offer_root_source BEFORE INSERT ON family_offer_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers c JOIN training_plans p ON p.customer_id=c.id JOIN schedule_slots s ON s.store_id=c.store_id WHERE c.id=NEW.customer_id AND c.store_id=NEW.store_id AND p.id=NEW.plan_id AND p.store_id=c.store_id AND s.id=NEW.slot_id AND p.created_at<=NEW.created_at AND s.created_at<=NEW.created_at) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM family_offer_roots WHERE store_id=NEW.store_id),1) OR NEW.offer_number IS NOT 'FO-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'family offer fixed customer/plan/slot/serial') END;END;
CREATE TRIGGER family_offer_version_source BEFORE INSERT ON family_offer_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_offer_roots r JOIN family_offer_sources m ON m.plan_id=r.plan_id AND m.slot_id=r.slot_id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND m.customer_id=r.customer_id AND m.plan_status='active' AND EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=r.recipient_id AND g.customer_id=r.customer_id AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(z.must_change_password,0)=0) AND NOT EXISTS(SELECT 1 FROM json_each(m.resources_json) j LEFT JOIN schedule_current_resources x ON x.resource_id=json_extract(j.value,'$.id') LEFT JOIN users u ON u.id=x.user_id LEFT JOIN user_security z ON z.user_id=u.id WHERE x.resource_id IS NULL OR x.version<>json_extract(j.value,'$.version') OR x.status<>'active' OR x.capacity<m.capacity OR x.kind='staff' AND (u.active<>1 OR u.role<>'professional' OR coalesce(z.must_change_password,0)<>0)) AND NEW.snapshot_json=json_object('plan_id',m.plan_id,'plan_number',m.plan_number,'customer_id',m.customer_id,'store_id',m.store_id,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'plan_version',m.plan_version,'plan_revision',m.plan_revision,'plan_event_id',m.plan_event_id,'plan_status',m.plan_status,'slot_id',m.slot_id,'slot_number',m.slot_number,'slot_revision',m.slot_revision,'slot_event_id',m.slot_event_id,'slot_kind',m.slot_kind,'capacity',m.capacity,'starts_at',m.starts_at,'ends_at',m.ends_at,'resources_json',m.resources_json) AND NEW.schedule_prefix=coalesce((SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id),0)) OR EXISTS(SELECT 1 FROM schedule_journal WHERE store_id=NEW.store_id AND sequence<=NEW.schedule_prefix AND created_at>NEW.created_at) OR json_extract(NEW.snapshot_json,'$.plan_event_id') NOT IN(SELECT id FROM training_plan_events WHERE created_at<=NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM family_offer_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM family_offer_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM family_offer_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'family offer current named source/version') END;END;
CREATE TRIGGER family_offer_event_source BEFORE INSERT ON family_offer_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_offer_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM family_offer_events WHERE root_id=NEW.root_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_offer_events WHERE store_id=NEW.store_id),1) OR NEW.action='publish' AND (NEW.status<>'published' OR NOT EXISTS(SELECT 1 FROM family_offer_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.base_sequence+1=NEW.sequence AND v.version=coalesce((SELECT max(v2.version)+1 FROM family_offer_events e JOIN family_offer_versions v2 ON v2.id=e.version_id WHERE e.root_id=NEW.root_id),1) AND EXISTS(SELECT 1 FROM family_offer_roots r JOIN family_offer_sources m ON m.plan_id=r.plan_id AND m.slot_id=r.slot_id WHERE r.id=v.root_id AND r.store_id=v.store_id AND m.customer_id=r.customer_id AND m.plan_status='active' AND EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=r.recipient_id AND g.customer_id=r.customer_id AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(z.must_change_password,0)=0) AND NOT EXISTS(SELECT 1 FROM json_each(m.resources_json) j LEFT JOIN schedule_current_resources x ON x.resource_id=json_extract(j.value,'$.id') LEFT JOIN users u ON u.id=x.user_id LEFT JOIN user_security z ON z.user_id=u.id WHERE x.resource_id IS NULL OR x.version<>json_extract(j.value,'$.version') OR x.status<>'active' OR x.capacity<m.capacity OR x.kind='staff' AND (u.active<>1 OR u.role<>'professional' OR coalesce(z.must_change_password,0)<>0)) AND v.snapshot_json=json_object('plan_id',m.plan_id,'plan_number',m.plan_number,'customer_id',m.customer_id,'store_id',m.store_id,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'plan_version',m.plan_version,'plan_revision',m.plan_revision,'plan_event_id',m.plan_event_id,'plan_status',m.plan_status,'slot_id',m.slot_id,'slot_number',m.slot_number,'slot_revision',m.slot_revision,'slot_event_id',m.slot_event_id,'slot_kind',m.slot_kind,'capacity',m.capacity,'starts_at',m.starts_at,'ends_at',m.ends_at,'resources_json',m.resources_json) AND v.schedule_prefix=coalesce((SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id),0)))) OR NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM family_offer_current e WHERE e.root_id=NEW.root_id AND e.version_id=NEW.version_id AND e.status='published')) THEN RAISE(ABORT,'family offer paired publication/event') END;END;
CREATE TRIGGER family_offer_selection_source BEFORE INSERT ON family_offer_selections BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_offer_roots r JOIN family_offer_current e ON e.root_id=r.id JOIN family_offer_versions v ON v.id=e.version_id JOIN family_offer_sources m ON m.plan_id=r.plan_id AND m.slot_id=r.slot_id JOIN family_request_roots q ON q.id=NEW.request_id JOIN family_request_events qe ON qe.id=q.first_event_id WHERE r.id=NEW.offer_id AND r.store_id=NEW.store_id AND e.status='published' AND v.id=NEW.version_id AND v.snapshot_json=json_object('plan_id',m.plan_id,'plan_number',m.plan_number,'customer_id',m.customer_id,'store_id',m.store_id,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'plan_version',m.plan_version,'plan_revision',m.plan_revision,'plan_event_id',m.plan_event_id,'plan_status',m.plan_status,'slot_id',m.slot_id,'slot_number',m.slot_number,'slot_revision',m.slot_revision,'slot_event_id',m.slot_event_id,'slot_kind',m.slot_kind,'capacity',m.capacity,'starts_at',m.starts_at,'ends_at',m.ends_at,'resources_json',m.resources_json) AND NEW.source_json=v.snapshot_json AND m.plan_status='active' AND EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=r.recipient_id AND g.customer_id=r.customer_id AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(z.must_change_password,0)=0) AND NOT EXISTS(SELECT 1 FROM json_each(m.resources_json) j LEFT JOIN schedule_current_resources x ON x.resource_id=json_extract(j.value,'$.id') LEFT JOIN users u ON u.id=x.user_id LEFT JOIN user_security z ON z.user_id=u.id WHERE x.resource_id IS NULL OR x.version<>json_extract(j.value,'$.version') OR x.status<>'active' OR x.capacity<m.capacity OR x.kind='staff' AND (u.active<>1 OR u.role<>'professional' OR coalesce(z.must_change_password,0)<>0)) AND NEW.request_prefix=(SELECT max(sequence) FROM family_request_events WHERE store_id=r.store_id) AND NEW.created_by=r.recipient_id AND q.customer_id=r.customer_id AND q.store_id=r.store_id AND q.recipient_id=r.recipient_id AND q.request_kind='appointment' AND q.time_status='recorded' AND q.requested_start=m.starts_at AND q.requested_end=m.ends_at AND q.created_at=NEW.created_at AND q.created_by=NEW.created_by AND qe.action='submit' AND qe.created_at=NEW.created_at AND qe.created_by=NEW.created_by AND NEW.offer_prefix=(SELECT max(sequence) FROM family_offer_events WHERE store_id=r.store_id) AND NEW.schedule_prefix=(SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id)) OR EXISTS(SELECT 1 FROM schedule_current_bookings b JOIN schedule_current_slots s ON s.slot_id=b.slot_id WHERE b.customer_id=(SELECT customer_id FROM family_offer_roots WHERE id=NEW.offer_id) AND b.status<>'cancelled' AND (b.slot_id=(SELECT slot_id FROM family_offer_roots WHERE id=NEW.offer_id) OR b.status='booked' AND s.starts_at<json_extract(NEW.source_json,'$.ends_at') AND json_extract(NEW.source_json,'$.starts_at')<s.ends_at)) OR EXISTS(SELECT 1 FROM family_offer_selections x JOIN family_offer_roots rr ON rr.id=x.offer_id JOIN family_request_current q ON q.root_id=x.request_id WHERE x.created_by=NEW.created_by AND rr.customer_id=(SELECT customer_id FROM family_offer_roots WHERE id=NEW.offer_id) AND rr.slot_id=(SELECT slot_id FROM family_offer_roots WHERE id=NEW.offer_id) AND q.status NOT IN('withdrawn','closed')) OR EXISTS(SELECT 1 FROM schedule_journal WHERE store_id=NEW.store_id AND sequence<=NEW.schedule_prefix AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM family_offer_events WHERE store_id=NEW.store_id AND sequence<=NEW.offer_prefix AND created_at>NEW.created_at) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at THEN RAISE(ABORT,'family offer current selection/duplicate/named source') END;END;
CREATE TRIGGER family_offer_admission_source BEFORE INSERT ON family_offer_admissions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM family_offer_selections x JOIN family_offer_roots r ON r.id=x.offer_id JOIN family_offer_current oe ON oe.root_id=r.id JOIN family_offer_versions v ON v.id=x.version_id JOIN family_offer_sources m ON m.plan_id=r.plan_id AND m.slot_id=r.slot_id JOIN family_request_current q ON q.root_id=x.request_id JOIN schedule_bookings b ON b.id=NEW.booking_id JOIN schedule_booking_events e ON e.id=NEW.booking_event_id WHERE x.id=NEW.selection_id AND x.store_id=NEW.store_id AND r.store_id=NEW.store_id AND oe.status='published' AND oe.version_id=v.id AND v.snapshot_json=json_object('plan_id',m.plan_id,'plan_number',m.plan_number,'customer_id',m.customer_id,'store_id',m.store_id,'cycle_id',m.cycle_id,'cycle_version',m.cycle_version,'plan_version',m.plan_version,'plan_revision',m.plan_revision,'plan_event_id',m.plan_event_id,'plan_status',m.plan_status,'slot_id',m.slot_id,'slot_number',m.slot_number,'slot_revision',m.slot_revision,'slot_event_id',m.slot_event_id,'slot_kind',m.slot_kind,'capacity',m.capacity,'starts_at',m.starts_at,'ends_at',m.ends_at,'resources_json',m.resources_json) AND m.plan_status='active' AND EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=r.recipient_id AND g.customer_id=r.customer_id AND g.active=1 AND u.active=1 AND u.role='guardian' AND coalesce(z.must_change_password,0)=0) AND NOT EXISTS(SELECT 1 FROM json_each(m.resources_json) j LEFT JOIN schedule_current_resources x ON x.resource_id=json_extract(j.value,'$.id') LEFT JOIN users u ON u.id=x.user_id LEFT JOIN user_security z ON z.user_id=u.id WHERE x.resource_id IS NULL OR x.version<>json_extract(j.value,'$.version') OR x.status<>'active' OR x.capacity<m.capacity OR x.kind='staff' AND (u.active<>1 OR u.role<>'professional' OR coalesce(z.must_change_password,0)<>0)) AND q.status NOT IN('withdrawn','closed') AND NEW.request_revision=q.revision AND NEW.offer_prefix=(SELECT max(sequence) FROM family_offer_events WHERE store_id=r.store_id) AND b.customer_id=r.customer_id AND b.store_id=r.store_id AND b.plan_id=r.plan_id AND b.plan_version=m.plan_version AND b.created_at=NEW.created_at AND b.created_by=NEW.created_by AND e.booking_id=b.id AND e.action='create' AND e.revision=1 AND e.slot_id=r.slot_id AND e.slot_revision=m.slot_revision AND e.plan_revision=m.plan_revision AND e.status IN('booked','waiting') AND e.created_at=NEW.created_at AND e.created_by=NEW.created_by AND e.sequence=(SELECT max(sequence) FROM schedule_journal WHERE store_id=r.store_id)) THEN RAISE(ABORT,'family offer explicit actual original admission') END;END;
CREATE TRIGGER family_offer_roots_actor BEFORE INSERT ON family_offer_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(z.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_offer_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family offer staff/time');END;
CREATE TRIGGER family_offer_versions_actor BEFORE INSERT ON family_offer_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(z.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_offer_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family offer staff/time');END;
CREATE TRIGGER family_offer_events_actor BEFORE INSERT ON family_offer_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(z.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_offer_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family offer staff/time');END;
CREATE TRIGGER family_offer_admissions_actor BEFORE INSERT ON family_offer_admissions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security z ON z.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(z.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_offer_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family offer staff/time');END;
CREATE TRIGGER family_offer_roots_no_update BEFORE UPDATE ON family_offer_roots BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_roots_no_delete BEFORE DELETE ON family_offer_roots BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_versions_no_update BEFORE UPDATE ON family_offer_versions BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_versions_no_delete BEFORE DELETE ON family_offer_versions BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_events_no_update BEFORE UPDATE ON family_offer_events BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_events_no_delete BEFORE DELETE ON family_offer_events BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_selections_no_update BEFORE UPDATE ON family_offer_selections BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_selections_no_delete BEFORE DELETE ON family_offer_selections BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_admissions_no_update BEFORE UPDATE ON family_offer_admissions BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_admissions_no_delete BEFORE DELETE ON family_offer_admissions BEGIN SELECT RAISE(ABORT,'family offer immutable');END;
CREATE TRIGGER family_offer_versions_text BEFORE INSERT ON family_offer_versions WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 BEGIN SELECT RAISE(ABORT,'family offer explicit text');END;
CREATE TRIGGER family_offer_events_text BEFORE INSERT ON family_offer_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'family offer explicit text');END;
